import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  inputGroupAddonClassesByAlign,
  inputGroupButtonClasses,
  inputGroupClasses,
  inputGroupControlClasses,
  inputGroupIconButtonClasses,
  inputGroupTextareaClasses,
  inputGroupTextClasses,
} from "./view";
import type { InputGroupAddonAlign } from "./view";

export type { InputGroupAddonAlign };

export {
  inputGroupAddonClassesByAlign,
  inputGroupButtonClasses,
  inputGroupClasses,
  inputGroupControlClasses,
  inputGroupIconButtonClasses,
  inputGroupTextareaClasses,
  inputGroupTextClasses,
} from "./view";

export type ViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
}>;

export type AddonViewConfig = Readonly<{
  children: readonly (Html | string)[];
  align?: InputGroupAddonAlign;
  className?: string;
}>;

export type InputViewConfig<ParentMessage> = Readonly<{
  placeholder?: string;
  ariaLabel?: string;
  value?: string;
  onInput?: ((value: string) => ParentMessage) | undefined;
  disabled?: boolean;
  name?: string;
  className?: string;
}>;

export type TextareaViewConfig<ParentMessage> = Readonly<{
  placeholder?: string;
  ariaLabel?: string;
  value?: string;
  onInput?: ((value: string) => ParentMessage) | undefined;
  disabled?: boolean;
  name?: string;
  rows?: number;
  className?: string;
}>;

export type ButtonViewConfig<ParentMessage> = Readonly<{
  children: readonly (Html | string)[];
  ariaLabel?: string;
  onClick?: ParentMessage;
  disabled?: boolean;
  icon?: boolean;
  className?: string;
}>;

const cn = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const view = <ParentMessage>({
  children,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      h.DataAttribute("slot", "input-group"),
      h.Class(cn(inputGroupClasses, className)),
    ],
    children
  );
};

export const addonView = <ParentMessage>({
  children,
  align = "InlineStart",
  className,
}: AddonViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      h.DataAttribute("slot", "input-group-addon"),
      h.DataAttribute("align", align),
      h.Class(cn(inputGroupAddonClassesByAlign(align), className)),
    ],
    children
  );
};

export const inputView = <ParentMessage>({
  placeholder,
  ariaLabel,
  value,
  onInput,
  disabled = false,
  name,
  className,
}: InputViewConfig<ParentMessage> = {}): Html => {
  const h = html<ParentMessage>();

  return h.input([
    h.DataAttribute("slot", "input-group-control"),
    h.Class(cn(inputGroupControlClasses, className)),
    ...(placeholder === undefined ? [] : [h.Placeholder(placeholder)]),
    ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
    ...(value === undefined ? [] : [h.Value(value)]),
    ...(onInput === undefined ? [] : [h.OnChange(onInput)]),
    ...(name === undefined ? [] : [h.Name(name)]),
    ...(disabled ? [h.Disabled(true)] : []),
  ]);
};

export const textareaView = <ParentMessage>({
  placeholder,
  ariaLabel,
  value,
  onInput,
  disabled = false,
  name,
  rows,
  className,
}: TextareaViewConfig<ParentMessage> = {}): Html => {
  const h = html<ParentMessage>();

  return h.textarea(
    [
      h.DataAttribute("slot", "input-group-control"),
      h.Class(cn(inputGroupTextareaClasses, className)),
      ...(placeholder === undefined ? [] : [h.Placeholder(placeholder)]),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(value === undefined ? [] : [h.Value(value)]),
      ...(onInput === undefined ? [] : [h.OnChange(onInput)]),
      ...(name === undefined ? [] : [h.Name(name)]),
      ...(rows === undefined ? [] : [h.Attribute("rows", String(rows))]),
      ...(disabled ? [h.Disabled(true)] : []),
    ],
    []
  );
};

export const buttonView = <ParentMessage>({
  children,
  ariaLabel,
  onClick,
  disabled = false,
  icon = false,
  className,
}: ButtonViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(onClick === undefined ? [] : [h.OnClick(onClick)]),
      ...(disabled ? [h.Disabled(true)] : []),
      h.Class(
        cn(
          icon ? inputGroupIconButtonClasses : inputGroupButtonClasses,
          className
        )
      ),
    ],
    children
  );
};

export const textView = <ParentMessage>(
  children: readonly (Html | string)[],
  className?: string
): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [h.Class(cn(inputGroupTextClasses, className))],
    children
  );
};

export type InputGroupAddonAlign =
  | "InlineStart"
  | "InlineEnd"
  | "BlockStart"
  | "BlockEnd";

export const inputGroupClasses =
  "relative flex h-9 min-w-0 items-center rounded-md border border-gray-300 bg-white text-gray-950 shadow-sm transition focus-within:border-accent-500 focus-within:ring-2 focus-within:ring-accent-100";

export const inputGroupControlClasses =
  "min-w-0 flex-1 rounded-none border-0 bg-transparent px-3 py-1 text-sm outline-none placeholder:text-gray-400 focus:ring-0";

export const inputGroupTextClasses =
  "flex items-center gap-2 text-sm text-gray-500";

export const inputGroupButtonClasses =
  "inline-flex h-7 shrink-0 items-center justify-center gap-1 rounded-md px-2 text-xs font-medium text-gray-700 transition hover:bg-gray-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500 disabled:pointer-events-none disabled:opacity-50";

export const inputGroupIconButtonClasses =
  "inline-flex size-7 shrink-0 items-center justify-center rounded-md text-gray-600 transition hover:bg-gray-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500 disabled:pointer-events-none disabled:opacity-50";

export const inputGroupTextareaClasses =
  "min-h-24 min-w-0 flex-1 resize-none rounded-none border-0 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-gray-400 focus:ring-0";

export const inputGroupAddonClassesByAlign = (
  align: InputGroupAddonAlign = "InlineStart"
): string => {
  if (align === "InlineEnd") {
    return "order-last flex items-center justify-center gap-1.5 pr-3 text-sm font-medium text-gray-500";
  }

  if (align === "BlockStart") {
    return "order-first flex w-full items-center justify-center gap-2 border-b border-gray-200 px-3 py-1.5 text-sm font-medium text-gray-500";
  }

  if (align === "BlockEnd") {
    return "order-last flex w-full items-center justify-center gap-2 border-t border-gray-200 px-3 py-1.5 text-sm font-medium text-gray-500";
  }

  return "order-first flex items-center justify-center gap-1.5 pl-3 text-sm font-medium text-gray-500";
};

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as InputGroup from "./index";

const view = (): Html => {
  const h = html<never>();

  return InputGroup.view({
    children: [
      InputGroup.inputView({
        ariaLabel: "Search",
        placeholder: "Search...",
      }),
      InputGroup.addonView({ children: ["S"] }),
      InputGroup.addonView({
        align: "InlineEnd",
        children: [
          h.kbd([], ["⌘"]),
          h.kbd([], ["K"]),
          InputGroup.buttonView({
            ariaLabel: "Search",
            children: ["Go"],
          }),
        ],
      }),
    ],
  });
};

const textareaView = (): Html =>
  InputGroup.view({
    children: [
      InputGroup.textareaView({
        ariaLabel: "Message",
        placeholder: "Type a message...",
        value: "Draft",
      }),
      InputGroup.addonView({
        align: "BlockEnd",
        children: [InputGroup.buttonView({ children: ["Send"] })],
      }),
    ],
  });

describe("InputGroup registry view", () => {
  test("renders grouped input, addons, and shortcut content", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("group")).toExist(),
      Scene.expect(Scene.role("textbox", { name: "Search" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Search" })).toExist(),
      Scene.expect(Scene.text("⌘")).toExist(),
      Scene.expect(Scene.text("K")).toExist()
    );
  });

  test("renders textarea controls and input group buttons", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view: textareaView,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("textbox", { name: "Message" })).toHaveValue(
        "Draft"
      ),
      Scene.expect(Scene.role("button", { name: "Send" })).toExist()
    );
  });
});
